// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title IoTDevicePool
 * @notice Manages connection pooling for IoT firmware update distribution
 * @dev Devices register, claim connection slots, then receive firmware chunks
 */
contract IoTDevicePool {
    struct Device {
        address owner;
        uint64 firmwareVersion;
        uint64 lastHeartbeat;
        bool registered;
        bool updating;
    }

    struct ConnectionSlot {
        bytes32 deviceId;
        uint256 allocatedAt;
        uint256 bandwidth;
        bool active;
    }

    struct FirmwareManifest {
        bytes32 checksum;
        uint256 size;
        uint64 version;
        bool approved;
        uint256 approvalTimestamp;
    }

    uint256 public constant MAX_POOL_SIZE = 32;
    uint256 public constant SLOT_TIMEOUT = 300; // 5 minutes
    uint256 public constant MIN_APPROVAL_DELAY = 2 days;

    address public admin;
    mapping(bytes32 => Device) public devices;
    ConnectionSlot[MAX_POOL_SIZE] public pool;
    mapping(bytes32 => FirmwareManifest) public manifests;
    mapping(bytes32 => mapping(uint256 => bytes32)) public firmwareChunks;

    uint256 private _activeConnections;
    mapping(bytes32 => uint256) private _deviceSlotIndex;
    mapping(bytes32 => bool) private _pendingUpgrade;

    event DeviceRegistered(bytes32 indexed deviceId, address owner);
    event SlotAllocated(bytes32 indexed deviceId, uint256 slotIndex);
    event FirmwareApplied(bytes32 indexed deviceId, uint64 newVersion);
    event ManifestSubmitted(bytes32 indexed manifestId);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    modifier onlyDeviceOwner(bytes32 deviceId) {
        require(devices[deviceId].owner == msg.sender, "Not device owner");
        _;
    }

    constructor() {
        admin = msg.sender;
    }

    function registerDevice(bytes32 deviceId, uint64 initialVersion) external {
        require(!devices[deviceId].registered, "Already registered");
        devices[deviceId] = Device({
            owner: msg.sender,
            firmwareVersion: initialVersion,
            lastHeartbeat: uint64(block.timestamp),
            registered: true,
            updating: false
        });
        emit DeviceRegistered(deviceId, msg.sender);
    }

    function submitManifest(bytes32 manifestId, bytes32 checksum, uint256 size, uint64 version) external onlyAdmin {
        manifests[manifestId] = FirmwareManifest({
            checksum: checksum,
            size: size,
            version: version,
            approved: false,
            approvalTimestamp: 0
        });
        emit ManifestSubmitted(manifestId);
    }

    function approveManifest(bytes32 manifestId) external onlyAdmin {
        FirmwareManifest storage m = manifests[manifestId];
        require(m.size > 0, "Manifest not found");
        m.approved = true;
        m.approvalTimestamp = block.timestamp;
    }

    /// @notice Request a connection slot for firmware download
    function requestSlot(bytes32 deviceId) external onlyDeviceOwner(deviceId) returns (uint256) {
        require(devices[deviceId].registered, "Not registered");
        require(!devices[deviceId].updating, "Already updating");
        require(_activeConnections < MAX_POOL_SIZE, "Pool full");

        uint256 slotIndex = _findFreeSlot();
        pool[slotIndex] = ConnectionSlot({
            deviceId: deviceId,
            allocatedAt: block.timestamp,
            bandwidth: _calculateBandwidth(),
            active: true
        });
        _deviceSlotIndex[deviceId] = slotIndex;
        _activeConnections++;

        emit SlotAllocated(deviceId, slotIndex);
        return slotIndex;
    }

    /// @notice Initiate firmware upgrade - checks manifest validity then marks device
    function beginUpgrade(bytes32 deviceId, bytes32 manifestId) external onlyDeviceOwner(deviceId) {
        require(_isSlotActive(deviceId), "No active slot");
        FirmwareManifest storage manifest = manifests[manifestId];

        // Validate manifest is approved and past timelock
        require(manifest.approved, "Manifest not approved");
        require(block.timestamp >= manifest.approvalTimestamp + MIN_APPROVAL_DELAY, "Timelock active");
        require(manifest.version > devices[deviceId].firmwareVersion, "Not an upgrade");

        // Mark upgrade as pending - device can now receive chunks
        _pendingUpgrade[deviceId] = true;
        devices[deviceId].updating = true;
    }

    /// @notice Apply firmware after all chunks received
    /// @dev The TOCTOU: we re-read manifest state but the slot validity check
    ///      uses cached _pendingUpgrade which was set when slot was valid
    function applyFirmware(bytes32 deviceId, bytes32 manifestId, bytes32 computedChecksum) external onlyDeviceOwner(deviceId) {
        require(_pendingUpgrade[deviceId], "No pending upgrade");

        FirmwareManifest storage manifest = manifests[manifestId];
        require(manifest.approved, "Manifest revoked");
        require(computedChecksum == manifest.checksum, "Checksum mismatch");

        // Apply the firmware version from manifest
        // VULNERABILITY: We don't re-verify that the slot is still active
        // An admin could have evicted the slot AND changed the manifest checksum
        // between beginUpgrade and applyFirmware, but _pendingUpgrade persists
        devices[deviceId].firmwareVersion = manifest.version;
        devices[deviceId].updating = false;
        _pendingUpgrade[deviceId] = false;

        _releaseSlot(deviceId);
        emit FirmwareApplied(deviceId, manifest.version);
    }

    /// @notice Admin can evict stale connections
    function evictSlot(uint256 slotIndex) external onlyAdmin {
        require(pool[slotIndex].active, "Slot not active");
        require(block.timestamp > pool[slotIndex].allocatedAt + SLOT_TIMEOUT, "Not timed out");

        bytes32 deviceId = pool[slotIndex].deviceId;
        pool[slotIndex].active = false;
        _activeConnections--;
        // Note: does NOT clear _pendingUpgrade[deviceId]
        // This is the TOCTOU gap - device still thinks upgrade is valid
    }

    /// @notice Admin can modify manifest checksum (e.g., if compromise detected)
    function updateManifestChecksum(bytes32 manifestId, bytes32 newChecksum) external onlyAdmin {
        require(manifests[manifestId].size > 0, "Manifest not found");
        // Update checksum - but devices with _pendingUpgrade set before this
        // can still call applyFirmware with the OLD checksum they computed
        // Wait - actually they pass computedChecksum as parameter...
        // The real issue: approved stays true, version stays same,
        // so a device whose slot was evicted can still apply with matching checksum
        manifests[manifestId].checksum = newChecksum;
    }

    function heartbeat(bytes32 deviceId) external onlyDeviceOwner(deviceId) {
        devices[deviceId].lastHeartbeat = uint64(block.timestamp);
    }

    function _isSlotActive(bytes32 deviceId) internal view returns (bool) {
        uint256 idx = _deviceSlotIndex[deviceId];
        return pool[idx].active && pool[idx].deviceId == deviceId;
    }

    function _findFreeSlot() internal view returns (uint256) {
        for (uint256 i = 0; i < MAX_POOL_SIZE; i++) {
            if (!pool[i].active) return i;
        }
        revert("No free slot");
    }

    function _calculateBandwidth() internal view returns (uint256) {
        if (_activeConnections == 0) return 1000;
        return 1000 / (_activeConnections + 1);
    }

    function _releaseSlot(bytes32 deviceId) internal {
        uint256 idx = _deviceSlotIndex[deviceId];
        if (pool[idx].active && pool[idx].deviceId == deviceId) {
            pool[idx].active = false;
            _activeConnections--;
        }
    }
}
